package coding::helper::enforce_quota;

use strict;
use warnings;
use Protocol7::Config;

sub enforce_quota {
    my ($job, $usage) = @_;

    # Read per-job byte quota from config; default is 4096
    my $quota = Protocol7::Config::get(
        'jobs',
        $job->{name},
        'byte_quota',
        4096
    );

    if ( $usage > $quota ) {
        warn "Job %s (%s) exceeded byte quota: %d / %d\n",
            $job->{name},
            $job->{id},
            $usage,
            $quota;
        return 0;
    }

    return 1;
}

1;
